windowclass.script:
function onClickDown(button, x, y)
				self.bringToFront();
			end

			function onInit()
				if Session.IsHost then
					makeStatTagsPublic();
				end

				if stattag_iadd then
					stattag_iadd.setVisible(Session.IsHost);
				end
			end

			function makeStatTagsPublic()
				local nodeList = DB.createNode("stattagg_list");
				if not nodeList then
					return;
				end

				nodeList.setPublic(true);

				for _, nodeEntry in pairs(DB.getChildren(nodeList)) do
					nodeEntry.setPublic(true);
				end
			end

button_iadd.script:
function onButtonPress()
						if not Session.IsHost then
							ChatManager.SystemMessage("GM only: only the Host can add entries here.");
							return true;
						end

						super.onButtonPress();

						if window.filter then
							window.filter.setValue();
						end

						return true;
					end

number.script:
--function onClickDown(x, y)
--	ModifierStack.addSlot("Mod", getValue());
--	ChatManager.SystemMessage("Mod added +2");
--end
--
function getActorName()
	local sActorName = "Actor";

	-- Desktop controls usually need the active player identity.
	local sIdentity = User.getCurrentIdentity();
	if sIdentity and sIdentity ~= "" then
		local nodeChar = DB.findNode("charsheet." .. sIdentity);
		if nodeChar then
			local rActor = ActorManager.resolveActor(nodeChar);
			if rActor then
				local sName = ActorManager.getDisplayName(rActor);
				if sName and sName ~= "" then
					return sName;
				end
			end

			local sName = DB.getValue(nodeChar, "name", "");
			if sName ~= "" then
				return sName;
			end
		end
	end

	-- Fallback for non-desktop / host-only windows.
	local nodeWin = window.getDatabaseNode();
	if nodeWin then
		local rActor = ActorManager.resolveActor(nodeWin);
		if rActor then
			local sName = ActorManager.getDisplayName(rActor);
			if sName and sName ~= "" then
				return sName;
			end
		end

		sActorName = DB.getValue(nodeWin, "name", "Actor");
	end

	return sActorName;
end

function getModifierText(nMod)
	if nMod >= 0 then
		return "+" .. nMod;
	end

	return tostring(nMod);
end

function onClickDown(x, y)
	local nMod = tonumber(getValue()) or 0;

	if nMod == 0 then
		return true;
	end

	ModifierStack.addSlot("Mod", nMod);

	local sActorName = getActorName();

	manager_modbutton.sendModButtonMessage(sActorName, nMod);

	return true;
end

