buttonfield.script:
local bThreatsMinimized = false;

					local aHideControls = {
						"stattagg_list",
						"stattagg_list_iadd",
						"plus1",
						"plus2",
						"plus3",
						"minus1",
						"minus2",
						"minus3",
					};

					local aGMOnlyControls = {
						"stattagg_list_iadd",	
					};

					function isGMOnlyControl(sControl)
						for _, sGMControl in ipairs(aGMOnlyControls) do
							if sControl == sGMControl then
								return true;
							end
						end

						return false;
					end

					function setControlVisibleAndEnabled(sControl, bVisible)
						if not window[sControl] then
							return;
						end

						if window[sControl].setVisible then
							window[sControl].setVisible(bVisible);
						end

						if window[sControl].setEnabled then
							window[sControl].setEnabled(bVisible);
						end

						if not bVisible and window[sControl].setValue then
							window[sControl].setValue(0);
						end
					end

					function setThreatsControlsVisible(bVisible)
						for _, sControl in ipairs(aHideControls) do
							if isGMOnlyControl(sControl) then
								setControlVisibleAndEnabled(sControl, bVisible and Session.IsHost);
							else
								setControlVisibleAndEnabled(sControl, bVisible);
							end
						end
					end

					function onButtonPress()
						bThreatsMinimized = not bThreatsMinimized;

						setThreatsControlsVisible(not bThreatsMinimized);

						if bThreatsMinimized then
							window.setSize(200, 50);
						else
							window.setSize(300, 300);
						end
					end
